const panel=document.querySelector('#panel');
const search=document.querySelector('.cataloghead input');
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function closeRoles(except){panel.querySelectorAll('.role').forEach(role=>{if(role!==except){role.classList.remove('open');role.querySelector('button').setAttribute('aria-expanded','false')}})}
function openRole(role){closeRoles(role);role.classList.add('open');role.querySelector('button').setAttribute('aria-expanded','true');const tip=role.querySelector('.tip');tip.style.left='0px';if(matchMedia('(min-width:701px)').matches){const box=tip.getBoundingClientRect();if(box.right>innerWidth-16)tip.style.left=`${innerWidth-16-box.right}px`;}}
let activeRoute=null;
function collapseRoute(){activeRoute=null;panel.hidden=true;closeRoles();document.querySelectorAll('.tab').forEach(t=>{t.setAttribute('aria-selected','false');t.setAttribute('aria-expanded','false')})}
function show(i){
 activeRoute=i;panel.hidden=false;
 document.querySelectorAll('.tab').forEach((t,j)=>(t.setAttribute('aria-selected',String(i===j)),t.setAttribute('aria-expanded',String(i===j)),t.setAttribute('aria-controls','panel')));
 const r=routes[i];
 panel.innerHTML=`<div><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p></div><div class="roles">${r.roles.map((x,j)=>`<div class="role"><button type="button" aria-expanded="false" aria-controls="role-${i}-${j}">${esc(x.label)} <span aria-hidden="true">⌄</span></button><div class="tip" id="role-${i}-${j}">${x.people.map(p=>`<div class="tip-person"><strong>${esc(p.name)}</strong><p>${esc(p.role)}</p><a href="#${p.id}">Показать в команде ↓</a>${p.url?`<a href="${esc(p.url)}">Подробнее о специалисте ↗</a>`:''}</div>`).join('')}</div></div>`).join('')}</div>`;
 panel.querySelectorAll('.role').forEach(role=>{
  const button=role.querySelector('button');
  button.onclick=e=>(e.pointerType!=='mouse'&&role.classList.contains('open'))?closeRoles():openRole(role);
  role.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')openRole(role)});
  role.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&!role.contains(document.activeElement))closeRoles()});
  role.addEventListener('focusout',()=>setTimeout(()=>{if(!role.contains(document.activeElement)){role.classList.remove('open');button.setAttribute('aria-expanded','false')}},0));
 });
}
const mobileRoutes=matchMedia('(max-width:700px)');
document.querySelectorAll('.tab').forEach((b,i)=>b.onclick=()=>{if(mobileRoutes.matches&&activeRoute===i)collapseRoute();else show(i)});
if(mobileRoutes.matches)collapseRoute();else show(0);
mobileRoutes.addEventListener('change',e=>{if(e.matches)collapseRoute();else show(activeRoute===null?0:activeRoute)});
search.oninput=e=>{const q=e.target.value.toLowerCase().trim();let n=0;document.querySelectorAll('.person').forEach(p=>{p.hidden=!p.dataset.search.includes(q);if(!p.hidden)n++});document.querySelector('.empty').style.display=n?'none':'block'};
document.addEventListener('click',e=>{
 const a=e.target.closest('a[href^="#person-"]');
 if(a){e.preventDefault();search.value='';document.querySelectorAll('.person').forEach(p=>p.hidden=false);document.querySelector('.empty').style.display='none';closeRoles();const target=document.querySelector(a.getAttribute('href'));history.replaceState(null,'',a.getAttribute('href'));target.focus({preventScroll:true});target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'})}
 else if(!e.target.closest('.role'))closeRoles();
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const button=panel.querySelector('.role.open>button');closeRoles();if(button)button.focus()}});
